<script setup lang="ts">
import {computed,nextTick,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {usePayrollPage} from '../payrollPage'
import {useSettlementCommand} from '../settlementCommand'
import {storeToday} from '../time'
import type {PayrollBoard,PayrollBoardRow} from '../payrollBoardTypes'
import type {BatchDetail} from '../payrollTypes'
import PayBreakdownSummary from './PayBreakdownSummary.vue'
import PayrollEvidence from './PayrollEvidence.vue'
import PhaseStatus from './PhaseStatus.vue'
const props=defineProps<{companyId:string;month:string;employeeId?:string|null}>(),emit=defineEmits<{locked:[value:boolean]}>()
const route=useRoute(),router=useRouter()
const {api,load,loading,failure,base,home,store,english,issue,r}=usePayrollPage(),command=useSettlementCommand(),data=ref<PayrollBoard|null>(null),search=ref(String(route.query.paySearch||'')),onlyIssues=ref(route.query.payIssues==='1'),expanded=ref(String(route.query.payEmployee||'')),confirmation=ref(false),note=ref('')
const {locked,uncertain,failure:commandFailure}=command,x=(z:string,e:string)=>english()?e:z
const rows=computed(()=>data.value?.rows.filter(row=>(!onlyIssues.value||row.issues.length)&&(!search.value||(row.employeeName+' '+row.employeeNo+' '+row.positionName).toLowerCase().includes(search.value.toLowerCase())))||[])
const own=computed(()=>!!props.employeeId&&!!data.value?.rows.some(row=>row.employeeId===props.employeeId))
const stage=computed(()=>{const d=data.value;if(!d)return 'loading';if(!d.rows.length&&d.segments?.length)return 'segmented';if(d.status==='published')return 'published';if(d.status==='confirmed')return 'publish';if(d.sourceChanged)return 'recalculate';if(d.issues.length)return 'prepare';if(d.status!=='calculated')return 'calculate';if(d.month>=storeToday().slice(0,7))return 'estimate';return 'confirm'})
const primaryLabel=computed(()=>({segmented:x('查看独立结薪与汇总','Independent settlements and totals'),loading:x('加载中','Loading'),prepare:x('处理待办','Resolve tasks'),calculate:x('开始测算','Calculate payroll'),recalculate:x('重新测算','Recalculate'),estimate:x('核对预估结果','Review estimate'),confirm:x('确认本月工资','Confirm monthly payroll'),publish:x('发布工资单','Publish payslips'),published:x('查看付款进度','View payments')}[stage.value]))
watch(locked,v=>emit('locked',v))
function refresh(){if(locked.value)return;data.value=null;confirmation.value=false;const company=props.companyId,month=props.month;if(!company||!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))return;void load(()=>api().get<PayrollBoard>('/employee-payroll-board?'+new URLSearchParams({companyId:company,month})),v=>{if(company!==props.companyId||month!==props.month)return;if(v.companyId!==company||v.month!==month||!Array.isArray(v.rows)||!Array.isArray(v.issues))throw new Error('Board scope mismatch');data.value=v;void nextTick(()=>{const scroll=String(route.query.payScroll||'');if(/^\d{1,6}$/.test(scroll)&&typeof window!=='undefined')window.scrollTo({top:Number(scroll)})})})}
watch(()=>[props.companyId,props.month],(_,previous)=>{if(previous){expanded.value='';search.value='';onlyIssues.value=false}refresh()},{immediate:true})
watch([search,onlyIssues,expanded],()=>{if(typeof router.replace==='function')void router.replace({query:{...route.query,companyId:props.companyId,month:props.month,paySearch:search.value||undefined,payIssues:onlyIssues.value?'1':undefined,payEmployee:expanded.value||undefined}})})
function returnContext(row:PayrollBoardRow){return {companyId:props.companyId,employeeId:row.employeeId,month:props.month,effectiveFrom:row.suggestedEffectiveFrom||undefined,fromPayroll:'1',returnStoreId:store.value,paySearch:search.value||undefined,payIssues:onlyIssues.value?'1':undefined,payEmployee:row.employeeId,payScroll:String(typeof window!=='undefined'?Math.max(0,Math.min(999999,Math.round(window.scrollY))):0)}}
function needsInput(row:PayrollBoardRow){return row.issues.some(c=>['UNITS_REQUIRED','SPECIAL_DAYS_REVIEW','NO_SOURCES_REVIEW'].includes(c))}
function prepareInput(row:PayrollBoardRow){if(locked.value||data.value?.batchId||data.value?.frozen||!needsInput(row))return;const company=props.companyId,month=props.month,id=crypto.randomUUID(),query=returnContext(row);return command.run<BatchDetail>('/payroll-batches/'+id,{companyId:company,month},'put',v=>v?.batch?.id===id&&v.batch.companyId===company&&v.batch.month===month,()=>{if(company===props.companyId&&month===props.month)queueMicrotask(()=>void router.push({path:base.value+'/payroll-batches/'+id+'/inputs/'+row.employeeId,query}))})}
function personAction(row:PayrollBoardRow){
 const query=returnContext(row),manage=home.value?.headOffice||home.value?.employeeManage
 if(row.issues.some(c=>c.startsWith('STATUTORY_POLICY')))return home.value?.headOffice?{path:base.value+'/statutory-policies',query}:null
 if(row.issues.some(c=>c.startsWith('WORK_MODE')))return manage?{path:base.value+'/employees/'+row.employeeId+'/edit',query}:null
 if(row.issues.some(c=>c.startsWith('PROFILE_')||c.startsWith('CPF_')||c.startsWith('CDAC_')||c==='CONTRACT_UNITS_INVALID'))return {path:base.value+'/pay-profiles/'+(row.profileId||'new'),query}
 if(row.issues.some(c=>['EVALUATION_REQUIRED','WORK_ARRANGEMENT_MISSING','MISSING_CLOCK_SOURCE','WEEK_CONTEXT_INCOMPLETE','PENDING_REQUEST'].includes(c)))return manage?{path:base.value+'/attendance',query}:null
 if(row.issues.some(c=>c.includes('APPROVAL')||c==='SOURCE_PENDING'||c==='ATTENDANCE_BONUS_REVIEW_REQUIRED')){
  const source=row.approvals?.[0]
  if(source)return home.value?.headOffice||home.value?.employeeManage&&store.value===source.storeId?{path:'/stores/'+source.storeId+'/workforce/attendance',query:{...query,attendanceMonth:source.workDate.slice(0,7)}}:null
  if(manage)return {path:base.value+'/attendance',query}
  return null
 }
 if(data.value?.batchId&&!data.value.frozen)return {path:base.value+'/payroll-batches/'+data.value.batchId+'/inputs/'+row.employeeId,query}
 return null
}
function primary(){if(!data.value||locked.value)return;if(stage.value==='prepare'){onlyIssues.value=true;const row=rows.value[0];if(row)expanded.value=row.employeeId;return}if(['confirm','publish'].includes(stage.value)){confirmation.value=true;return}if(['calculate','recalculate'].includes(stage.value))void execute()}
function calculateCreated(value:BatchDetail,company:string,month:string){if(company!==props.companyId||month!==props.month){refresh();return}const id=value.batch.id;const request=command.run<BatchDetail>('/payroll-batches/'+id+'/actions/'+crypto.randomUUID(),{expectedVersion:value.batch.version,action:'calculate',note:x('月度工资测算','Monthly payroll calculation')},'put',v=>v?.batch?.id===id&&v.batch.companyId===company&&v.batch.month===month,()=>{});void request?.then(()=>{if(!uncertain.value)refresh()})}
function execute(){const d=data.value;if(!d||locked.value)return;const company=props.companyId,month=props.month;const id=d.batchId||crypto.randomUUID();const create=!d.batchId;const action=stage.value==='publish'?'publish':stage.value==='confirm'?'confirm':'calculate';if(!create&&['confirm','publish'].includes(action)&&(!note.value.trim()||own.value))return;const path=create?'/payroll-batches/'+id:'/payroll-batches/'+id+'/actions/'+crypto.randomUUID();const body=create?{companyId:company,month}:{expectedVersion:d.batchVersion,action,note:note.value.trim()||x('月度工资测算','Monthly payroll calculation')};return command.run<BatchDetail>(path,body,'put',v=>v?.batch?.id===id&&v.batch.companyId===company&&v.batch.month===month,value=>{confirmation.value=false;note.value='';queueMicrotask(()=>{if(create&&value.batch.status==='draft')calculateCreated(value,company,month);else refresh()})})}
</script>
<template><section class="wf-section guided-payroll">
<header class="wf-toolbar"><div><h3>{{x('本月工资','Monthly payroll')}}</h3><p class="wf-hint">{{month}} · {{data?.segments?.length?x('普通工资范围','Ordinary payroll scope'):x('公司全量','Whole company')}} {{data?.rows.length??'—'}} {{x('人','employees')}}</p></div><button :disabled="loading||locked" @click="refresh">{{x('刷新','Refresh')}}</button></header>
<PhaseStatus :loading="loading" :failure="failure||commandFailure"/>
<template v-if="data"><p class="wf-hint">{{x('准备资料 → 本月测算 → 核对结果 → 正式确认 → 发布工资单','Prepare → Calculate → Review → Confirm → Publish')}}</p>
<section v-if="data.segments?.length" class="wf-section"><h4>{{x('已独立结薪，月底不再重复整月确认','Independently settled; excluded from ordinary full-month confirmation')}}</h4><p v-for="s in data.segments" :key="s.id">{{s.employeeName}} · {{s.from}} – {{s.cutoff}} · {{x('本次应实发','Net')}} {{s.net}} <span v-if="s.sourceChanged" role="status">{{x('已结来源有变更：需独立补发／纠错','Settled sources changed: separate correction required')}}</span> <RouterLink :to="{path:base+'/payroll-segments',query:{companyId,month,segmentId:s.id}}">{{x('查看／后续结薪','View / settle next period')}}</RouterLink></p><RouterLink :to="{path:base+'/payroll-segments',query:{companyId,month}}">{{x('统一月底汇总与付款对账','Unified month reconciliation and payments')}}</RouterLink></section><div class="wf-toolbar"><p v-if="stage==='segmented'">{{x('普通整月待结范围为空；未结后续期间请从独立结薪继续办理。','No ordinary full-month recipients. Continue unsettled later periods using independent settlement.')}}</p><p v-else-if="stage==='prepare'" role="status">{{x('先处理下列待办，完成后返回测算。未知金额不代表零工资。','Resolve tasks, then calculate. Unknown amounts are not zero wages.')}}</p><p v-else-if="stage==='recalculate'" role="status">{{x('工时或薪资来源已变化，需要重新测算。','Hours or pay sources changed. Recalculate payroll.')}}</p><p v-else-if="stage==='estimate'">{{x('本月尚未结束，当前仅为测算；普通月度工资需月底后正式确认。','Month still open: estimate only. Regular payroll can be confirmed after month end.')}}</p><p v-else-if="stage==='published'">{{x('工资单已发布；付款单独登记，不代表银行到账。','Payslips published. Register payments separately; publication is not bank receipt.')}}</p><p v-else>{{x('按当前进度办理下一步。','Continue with the next step.')}}</p>
<RouterLink v-if="stage==='segmented'" class="wf-button primary" :to="{path:base+'/payroll-segments',query:{companyId,month}}">{{primaryLabel}}</RouterLink><RouterLink v-else-if="stage==='published'&&data.batchId" class="wf-button primary" :to="base+'/payroll-batches/'+data.batchId">{{primaryLabel}}</RouterLink><button v-else-if="stage!=='estimate'" class="primary" :disabled="locked||loading||(!data.rows.length)||(['confirm','publish'].includes(stage)&&own)" @click="primary">{{primaryLabel}}</button></div>
<p v-if="own" class="wf-hint">{{x('此批次包含本人，正式确认和发布需由其他授权人办理。','This batch includes your salary. Another authorized person must confirm and publish.')}}</p>
<div v-if="data.totals" class="payroll-totals"><strong>{{x('应发','Gross')}} SGD {{data.totals.gross}}</strong><strong>{{x('应实发','Net payable')}} SGD {{data.totals.net}}</strong><span>{{x('公司总成本','Company cost')}} SGD {{data.totals.employerCost}}</span></div><p v-else class="wf-hint">{{x('全量金额待资料齐全并完成有效测算后显示。','Company totals are available after complete, current calculation.')}}</p>
<div v-if="confirmation" class="wf-section" role="region" :aria-label="primaryLabel"><h4>{{primaryLabel}}</h4><p>{{month}} · {{x('公司全量','Whole company')}} {{data.rows.length}} {{x('人；包含当前筛选外','employees; includes')}} {{data.rows.length-rows.length}} {{x('人。此操作作用于整批工资。','outside the filter. This action applies to the whole batch.')}}</p><p>{{x('应实发','Net payable')}} SGD {{data.totals?.net??'—'}} · {{x('公司总成本','Company cost')}} {{data.totals?.employerCost??'—'}}</p><p>{{stage==='publish'?x('发布后员工可查看工资单，付款仍需单独登记。','Publishing makes payslips visible. Payment is registered separately.'):x('确认后冻结工资依据及金额；后续错误需独立纠错。','Confirmation freezes sources and amounts. Later corrections are separate.')}}</p><label>{{x('办理说明','Note')}}<textarea v-model="note" maxlength="500" rows="2" :disabled="locked"/></label><div class="wf-inline"><button :disabled="locked" @click="confirmation=false">{{x('取消','Cancel')}}</button><button class="primary" :disabled="locked||!note.trim()||own" @click="execute">{{primaryLabel}}</button></div></div>
<div class="wf-filters"><label>{{x('姓名 / 员工编号 / 岗位','Name / employee no. / position')}}<input v-model="search" type="search"></label><label class="wf-inline"><input v-model="onlyIssues" type="checkbox">{{x('只看待办','Tasks only')}}</label></div>
<div class="wf-table-wrap"><table class="payroll-employee-table"><thead><tr><th>{{x('员工','Employee')}}</th><th>{{x('岗位 / 方式','Position / basis')}}</th><th>{{x('应发','Gross')}}</th><th>{{x('员工扣款','Employee deductions')}}</th><th>{{x('应实发','Net payable')}}</th><th>{{x('状态 / 下一步','Status / next step')}}</th></tr></thead><tbody><template v-for="row in rows" :key="row.employeeId"><tr class="payroll-person-row"><td><button class="employee-name" :aria-expanded="expanded===row.employeeId" @click="expanded=expanded===row.employeeId?'':row.employeeId">{{row.employeeName}}</button><br><small>{{row.employeeNo}}</small></td><td :data-label="x('岗位 / 方式','Position / basis')">{{row.positionName||(data.frozen?x('岗位未留存','Position not retained'):x('未记录岗位','Position not recorded'))}} · {{row.basis?r(row.basis as 'monthly'|'hourly'|'daily'):'—'}}</td><td :data-label="x('应发','Gross')">{{row.gross??'—'}}</td><td :data-label="x('员工扣款','Employee deductions')">{{row.deductions??'—'}}</td><td :data-label="x('应实发','Net payable')">{{row.net??'—'}}</td><td><span v-if="!row.issues.length">{{data.frozen?x('已正式结薪','Confirmed'):data.sourceChanged?x('待重算','Recalculate'):row.net===null?x('待测算','Calculate'):x('测算完成','Calculated')}}</span><RouterLink v-else-if="personAction(row)" :to="personAction(row)!">{{row.issues.includes('PROFILE_MISSING')?x('配置薪资','Configure salary'):x('处理待办','Resolve tasks')}} ({{row.issues.length}})</RouterLink><button v-else-if="needsInput(row)&&!data.batchId&&!data.frozen" :disabled="locked" @click="prepareInput(row)">{{x('填写本月资料','Enter monthly inputs')}}</button><span v-else>{{row.approvals?.length?x('请来源门店有权人核准','Source-store reviewer required'):x('需核对','Review required')}}</span></td></tr><tr v-if="expanded===row.employeeId" class="payroll-detail-row"><td colspan="6"><section class="employee-pay-detail"><h4>{{row.employeeName}} · {{month}}</h4><ul v-if="row.issues.length"><li v-for="code in row.issues" :key="code">{{issue(code)}}</li></ul><template v-if="row.breakdown"><PayBreakdownSummary :value="row.breakdown" details business-labels/><details v-if="row.line"><summary>{{x('查看工时与计算依据','View hours and calculation evidence')}}</summary><PayrollEvidence :line="row.line"/></details></template><p v-else>{{x('金额待有效测算；请先完成待办或重新测算。','Amounts need a current calculation. Resolve tasks or recalculate.')}}</p><div class="wf-inline"><RouterLink v-if="row.profileId" :to="{path:base+'/pay-profiles/'+row.profileId,query:returnContext(row)}">{{x('薪资待遇','Pay terms')}}</RouterLink><RouterLink v-if="data.frozen" :to="{path:base+'/supplemental-payroll',query:{companyId,employeeId:row.employeeId,originMonth:month,originalBatchId:data.batchId}}">{{x('个人补发 / 付款查询','Supplemental pay / payments')}}</RouterLink></div></section></td></tr></template><tr v-if="!rows.length"><td colspan="6" class="wf-empty">{{x('没有符合条件的员工','No matching employees')}}</td></tr></tbody></table></div>
<p class="wf-hint">{{x('筛选只影响查看；正式确认始终针对公司全量，不要求逐人打开明细。','Filters affect viewing only. Confirmation covers the whole company; opening every person is not required.')}}</p>
</template><button v-if="uncertain" :disabled="command.busy.value" @click="command.replay">{{x('重试原操作','Retry original action')}}</button>
</section></template>
<style scoped>.guided-payroll .wf-filters label.wf-inline{display:inline-flex;align-items:center;gap:8px;min-width:0;flex:0 0 auto}.guided-payroll .wf-filters input[type="checkbox"]{width:18px;height:18px;min-height:0;padding:0;margin:0;flex:0 0 auto}.payroll-totals{display:flex;flex-wrap:wrap;gap:16px;margin:14px 0}.employee-name{background:transparent;border:0;padding:0;color:var(--color-primary,#245a7d);text-decoration:underline}.employee-pay-detail{padding:12px;min-width:0;overflow-wrap:anywhere}.guided-payroll{min-width:0}.wf-table-wrap table{width:100%}@media(max-width:600px){.payroll-totals{flex-direction:column;gap:6px}}@media(max-width:600px){.payroll-employee-table{display:block;white-space:normal}.payroll-employee-table>thead{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.payroll-employee-table>tbody{display:block}.payroll-person-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));border-top:1px solid #e0e5ec}.payroll-person-row>td{min-width:0;overflow-wrap:anywhere;border:0;white-space:normal}.payroll-person-row>td:first-child,.payroll-person-row>td:last-child{grid-column:1/-1}.payroll-person-row>td[data-label]::before{content:attr(data-label);display:block;color:#718096;font-size:12px;margin-bottom:3px}.payroll-detail-row,.payroll-detail-row>td{display:block;min-width:0;white-space:normal}.employee-pay-detail{padding:0}}
</style>
